// The Tier 3 preview corpus, typed — the only thing that can answer "what bytes would be sent?"
// without a backend.
//
// `src/case-preview-corpus.json` is GENERATED by `case_preview_corpus_matches_what_this_module_
// produces` in `src-tauri/src/case_evidence_upload.rs`, which also fails if the committed file
// stops matching `case_preview()`. So every string this module hands out is real output of the one
// canonical serializer, not a TypeScript re-implementation of it. That is deliberate: contract §3
// pins preview-source == send-source, and a second serializer in another language is the exact
// drift §3 exists to prevent.
//
// It is fixture-only. Nothing in the shipped app imports it (`reachability-guard` carries the entry
// and the reason, and `src/case-evidence-consent-guard.test.ts` fails the build if a src/ module
// ever does); at Stage 4 the consent screen's `preview` prop takes the Tauri command instead and
// this module is deleted with the fixture that used it.

import corpus from "./case-preview-corpus.json";
import type { CasePreviewText, CaseRemovableUnit } from "./surfaces/CaseEvidenceConsent";

export type CaseCorpusBase = "both" | "comment-only";

type CorpusEntry = { base: string; removed: string[]; shape: string; payload_json: string };

const entries = corpus.entries as CorpusEntry[];

/** Order-independent: the corpus enumerates SETS, and the screen removes in whatever order a user clicks. */
const key = (base: string, removed: readonly string[]) => `${base}|${[...removed].sort().join(",")}`;

const byKey = new Map<string, CorpusEntry>(entries.map((e) => [key(e.base, e.removed), e]));

/** The removable units the corpus really enumerates for a base — never a hand-kept second list. */
export function corpusRemovable(base: CaseCorpusBase): CaseRemovableUnit[] {
  return (corpus.removable_units as Record<string, string[]>)[base] as CaseRemovableUnit[];
}

/**
 * The `preview` prop, backed by real Rust output.
 *
 * A miss THROWS rather than returning null: null is the screen's honest "this case has no shape"
 * state, and quietly borrowing it for "the corpus is missing an entry" would paint a truthful-
 * looking empty state over a broken fixture. Every reachable removal set is enumerated, so a miss
 * means the corpus and the screen disagree about what is reachable — which is a defect, loudly.
 */
export function corpusPreview(base: CaseCorpusBase, removed: readonly CaseRemovableUnit[]): CasePreviewText {
  const hit = byKey.get(key(base, removed));
  if (!hit) {
    throw new Error(
      `case-preview corpus has no entry for ${key(base, removed)} — regenerate it with ` +
        `COMPY_UPDATE_CASE_PREVIEW_CORPUS=1 cargo test case_preview_corpus`,
    );
  }
  return { shape: hit.shape, payload_json: hit.payload_json };
}

export const corpusEntries = (): readonly CorpusEntry[] => entries;
export const corpusShapes = (): readonly string[] => corpus.shapes as string[];
